# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_ai_inline_command() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _argc_util_comp_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_config_key() {
    atuin config print 2>/dev/null | gawk '
        /^[[:space:]]*\[\[?.*\]\][[:space:]]*$/ {
            section = $0
            sub(/^[[:space:]]*\[+/, "", section)
            sub(/\]+[[:space:]]*$/, "", section)
            next
        }
        /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
            key = $0
            sub(/[[:space:]]*=.*$/, "", key)
            sub(/^[[:space:]]*/, "", key)
            if (section != "") print section "." key
            else print key
        }'
}

_choice_dotfiles_alias_name() {
    atuin dotfiles alias list 2>/dev/null | sed 's/=.*$//'
}

_choice_dotfiles_alias_value() {
    atuin dotfiles alias list 2>/dev/null | sed 's/^[^=]*=//'
}

_choice_dotfiles_var_name() {
    atuin dotfiles var list 2>/dev/null | sed 's/^export //; s/=.*$//'
}

_choice_dotfiles_var_value() {
    atuin dotfiles var list 2>/dev/null | sed 's/^[^=]*=//'
}

_choice_history_author() {
    _argc_util_cache 300 _helper_history_author_uncached "atuin_history_author_${ATUIN_DATA_DIR:-home}"
}

_choice_history_start_command() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _argc_util_comp_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_history_year() {
    _argc_util_cache 3600 _helper_history_year_uncached "atuin_history_year_${ATUIN_DATA_DIR:-home}"
}

_choice_hook_agent() {
    printf '%s\n' amp claude-code codex copilot grok hermes kiro opencode pi omp
}

_choice_kv_key() {
    if [[ -n "${argc_namespace:-}" ]]; then
        atuin kv list -n "$argc_namespace" 2>/dev/null
    else
        atuin kv list 2>/dev/null
    fi
}

_choice_kv_namespace() {
    atuin kv list -a 2>/dev/null | sed 's/\..*$//'
}

_choice_script_file() {
    _argc_util_comp_path
}

_choice_scripts_name() {
    atuin scripts list 2>/dev/null | gawk '/^- / { print $2 }'
}

_choice_scripts_var() {
    [[ -n "${argc_name:-}" ]] || return 0
    atuin scripts get "$argc_name" --script 2>/dev/null | gawk '
        {
            line = $0
            while (match(line, /\{\{[A-Za-z0-9_.-]+\}\}/)) {
                key = substr(line, RSTART + 2, RLENGTH - 4)
                if (!seen[key]++) print key "="
                line = substr(line, RSTART + RLENGTH)
            }
        }' | _argc_util_comp_kv =
}

_choice_setup_sync() {
    printf '%s\n' cloud off
}

_choice_shell() {
    [[ -f /etc/shells ]] || return 0
    grep -v '^[[:space:]]*#' /etc/shells | grep -v '^[[:space:]]*$'
}

_choice_stats_period() {
    printf '%s\t%s\n' \
        all 'Entire history' \
        today 'Since local midnight' \
        week 'Last 7 days' \
        month 'Last 31 days' \
        year 'Last 365 days'
}

_choice_store_host() {
    atuin store status 2>/dev/null | gawk '/^[[:space:]]*host: / { print $2 }'
}

_choice_store_tag() {
    atuin store status 2>/dev/null | gawk '/^[[:space:]]*store: / { print $2 }'
}

_choice_threads_branch() {
    printf '%s\n' this
    atuin threads list --style json 2>/dev/null | jq -b -r '.[] | "@" + .host'
}

_choice_threads_id() {
    printf '%s\n' latest
    atuin threads list --style json 2>/dev/null | jq -b -r '.[] | .atuin_id, .session_id'
}

_choice_threads_session() {
    atuin threads list --style json 2>/dev/null \
        | jq -b -r --arg harness "${argc_harness:-}" '.[] | select($harness == "" or .harness == $harness) | .session_id'
}

_choice_timezone() {
    if command -v timedatectl >/dev/null 2>&1; then
        local zones
        zones=$(timedatectl list-timezones 2>/dev/null) || zones=""
        if [[ -n "$zones" ]]; then
            printf '%s\n' "$zones"
            return 0
        fi
    fi
    [[ -d /usr/share/zoneinfo ]] || return 0
    (
        cd /usr/share/zoneinfo || exit 0
        find . -type f ! -name '*.*' ! -path './posix/*' ! -path './right/*' -print
    ) | sed 's|^\./||'
}

_helper_history_author_uncached() {
    atuin history list --format '{author}' 2>/dev/null \
        | gawk 'NF && !seen[$0]++ { print; if (++n >= 100) exit }'
}

_helper_history_year_uncached() {
    atuin history list --format '{time}' 2>/dev/null | gawk '
        { year = substr($0, 1, 4) }
        year ~ /^[0-9][0-9][0-9][0-9]$/ && !seen[year]++ { print year }'
}
